const updateMeeting = `-- name: UpdateMeeting :one
UPDATE meetings SET title = $4, scheduled_start = $5, scheduled_end = $6
WHERE id = $1 AND tenant_id = $2 AND owner_user_id = $3 AND status <> 'canceled' RETURNING id, tenant_id, owner_user_id, title, room_name, scheduled_start, scheduled_end, actual_start, actual_end, status, event_id, created_at, access, allow_mic, allow_cam, allow_share, allow_chat, lock_until_host, locked
`

type UpdateMeetingParams struct {
	ID             uuid.UUID          `json:"id"`
	TenantID       uuid.UUID          `json:"tenant_id"`
	OwnerUserID    uuid.UUID          `json:"owner_user_id"`
	Title          string             `json:"title"`
	ScheduledStart pgtype.Timestamptz `json:"scheduled_start"`
	ScheduledEnd   pgtype.Timestamptz `json:"scheduled_end"`
}

// Edit/reschedule: only the owner, and only a non-canceled meeting. Returns the row to sync the event.
func (q *Queries) UpdateMeeting(ctx context.Context, arg UpdateMeetingParams) (Meeting, error) {
	row := q.db.QueryRow(ctx, updateMeeting,
		arg.ID,
		arg.TenantID,
		arg.OwnerUserID,
		arg.Title,
		arg.ScheduledStart,
		arg.ScheduledEnd,
	)
	var i Meeting
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.OwnerUserID,
		&i.Title,
		&i.RoomName,
		&i.ScheduledStart,
		&i.ScheduledEnd,
		&i.ActualStart,
		&i.ActualEnd,
		&i.Status,
		&i.EventID,
		&i.CreatedAt,
		&i.Access,
		&i.AllowMic,
		&i.AllowCam,
		&i.AllowShare,
		&i.AllowChat,
		&i.LockUntilHost,
		&i.Locked,
	)
	return i, err
}

