const upsertMeetingNotes = `-- name: UpsertMeetingNotes :one
INSERT INTO meeting_notes (meeting_id, tenant_id, body, updated_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (meeting_id) DO UPDATE
  SET body = EXCLUDED.body, updated_by = EXCLUDED.updated_by, updated_at = now()
RETURNING meeting_id, tenant_id, body, updated_by, updated_at
`

type UpsertMeetingNotesParams struct {
	MeetingID uuid.UUID   `json:"meeting_id"`
	TenantID  uuid.UUID   `json:"tenant_id"`
	Body      string      `json:"body"`
	UpdatedBy pgtype.UUID `json:"updated_by"`
}

func (q *Queries) UpsertMeetingNotes(ctx context.Context, arg UpsertMeetingNotesParams) (MeetingNote, error) {
	row := q.db.QueryRow(ctx, upsertMeetingNotes,
		arg.MeetingID,
		arg.TenantID,
		arg.Body,
		arg.UpdatedBy,
	)
	var i MeetingNote
	err := row.Scan(
		&i.MeetingID,
		&i.TenantID,
		&i.Body,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}
